var i=[{title:`Zakres bierny i czynny`,text:`Możesz być w stanie unieść ramię nad głowę z pomocą, ale mieć trudność z uniesieniem go tam samodzielnie. Wskazuje to na wystarczającą elastyczność bez takiej samej siły lub koordynacji w tym zakresie. Inne osoby mają naprawdę ograniczony wygodny zakres i mogą skorzystać ze stopniowego rozciągania lub innego wariantu ćwiczenia.`},{title:`Przetestuj ruchy, których używasz`,text:`Kontrolowane sięgnięcie nad głowę, wygodny przysiad z masą ciała lub zawias biodrowy mogą pokazać, czy ruch z Twojego treningu wydaje się ograniczony. Porównaj strony, ale nie wymuszaj, by były takie same. Chodzi o wychwycenie praktycznego ograniczenia. Nie jest to diagnoza przyczyny napięcia, bólu stawu ani schorzenia.`},{title:`Trenuj kontrolę w zakresie, który masz`,text:`Dynamiczne krążenia ramion, kontrolowane wykroki, rotacje piersiowe i powolne ruchy bioder pozwalają ćwiczyć zakresy pod aktywną kontrolą. Ćwiczenia siłowe wykonywane w wygodnym zakresie i rozwijane z czasem mogą też poprawiać ruchomość. Rozciąganie statyczne poprawia elastyczność, ale samo nie zawsze buduje kontrolę.`},{title:`Nie ma jednego idealnego zakresu`,text:`Proporcje ciała, budowa stawów, historia kontuzji i umiejętności wpływają na to, które ruchy są wygodne. Nie potrzebujesz maksymalnie głębokiego przysiadu ani skrajnej elastyczności barków, by dobrze trenować. Wybierz zakres, w którym technika pozostaje stabilna i bezbolesna, i stopniowo od niego buduj.`},{title:`Korzystanie z TrainUp`,text:`Jeśli jakaś część ciała ogranicza Twój zakres, dodaj ją jako ograniczenie w Profilu, z notatką. Plan wybierze wtedy ćwiczenia pasujące do Twoich ograniczeń, poziomu i koordynacji. Strona każdego ćwiczenia w zakładce Ćwiczenia zawiera kroki i notatki o technice. Zapytaj lekarza lub fizjoterapeutę o ograniczenie, które się utrzymuje, niewyjaśniony ból lub objawy wpływające na codzienne życie.`}];var o=[{label:`ACE 2026: ruchomość a elastyczność`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE 2026: praktyczne wskazówki dotyczące rozciągania`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:i,sources:o};export{n as default,i as sections,o as sources};